h1 { margin: 0; font-size: 24px; letter-spacing: .3px; }
.sub { margin: 6px 0 0; color: var(--dim); font-size: 14px; }
.progressbox { min-width: 210px; text-align: right; }
.pnum { font-size: 28px; font-weight: 700; color: var(--accent); }
.plabel { font-size: 12px; color: var(--dim); text-transform: uppercase; letter-spacing: 1px; }
.pbar { margin-top: 6px; height: 8px; border-radius: 99px; background: var(--panel2); overflow: hidden; }
.pfill { height: 100%; width: 0%; background: linear-gradient(90deg, var(--accent), var(--accent2)); transition: width .25s; }

.controls { display: flex; gap: 10px; flex-wrap: wrap; align-items: center;
  padding: 14px 28px; background: var(--panel); border-bottom: 1px solid var(--line); }
.controls input[type="search"], .controls select, .controls button {
  background: var(--panel2); color: var(--ink); border: 1px solid var(--line);
  border-radius: 8px; padding: 7px 11px; font-size: 14px; }
.controls input[type="search"] { min-width: 210px; }
.controls button { cursor: pointer; }
.controls button:hover { border-color: var(--accent); }
.chk { display: inline-flex; align-items: center; gap: 6px; font-size: 13px; color: var(--dim); }
.import { font-size: 13px; color: var(--dim); cursor: pointer; }
.import input { display: none; }
button.danger { margin-left: auto; }

.roadmap { padding: 16px 28px 4px; }
.roadmap h2 { font-size: 17px; margin: 8px 0 10px; }
.roadmap .hint { font-weight: 400; color: var(--dim); font-size: 13px; }
.roadmap ol { margin: 0; padding-left: 22px; color: var(--dim); font-size: 14px; line-height: 1.9; }
.roadmap li b { color: var(--ink); }
.roadmap .miss { color: var(--accent); }

main { padding: 8px 28px 30px; }
.summary { margin: 12px 0; padding: 12px 16px; background: var(--panel2);
  border: 1px solid var(--line); border-radius: 10px; font-size: 13px; color: var(--dim); }

.trophies { display: grid; gap: 10px; }
.tcard { display: grid; grid-template-columns: 34px 1fr 130px; gap: 12px;
  background: var(--panel); border: 1px solid var(--line); border-radius: 12px; padding: 12px 14px; }
.tcard.earned { opacity: .55; }
.tcard .box { display: flex; align-items: flex-start; padding-top: 2px; }
.tcard .box input { width: 18px; height: 18px; accent-color: var(--ok); cursor: pointer; }
.tname { font-weight: 600; font-size: 15px; margin: 0; }
.tdesc { color: var(--dim); font-size: 13px; margin: 3px 0 6px; }
.tguide { font-size: 13.5px; line-height: 1.5; color: #c6cfe0; }
.tguide .src { color: var(--dim); font-style: italic; font-size: 12px; }
.badges { display: flex; flex-direction: column; gap: 5px; align-items: flex-end; }
.grade { font-size: 11px; text-transform: uppercase; letter-spacing: .8px;
  padding: 2px 9px; border-radius: 99px; border: 1px solid currentColor; }
.grade.platinum { color: var(--plat); }
.grade.gold { color: var(--gold); }
.grade.silver { color: var(--silver); }
.grade.bronze { color: var(--bronze); }
.tags { display: flex; gap: 5px; flex-wrap: wrap; justify-content: flex-end; }
.tag { font-size: 11px; color: var(--dim); border: 1px solid var(--line); border-radius: 99px; padding: 1px 8px; }
.tag.miss { color: var(--accent); border-color: #5a4514; }
.tag.kind { color: #9fb4ff; border-color: #2d3a66; }

footer { padding: 18px 28px 26px; border-top: 1px solid var(--line); color: var(--dim); font-size: 12px; line-height: 1.6; }
@media (max-width: 760px) {
  .tcard { grid-template-columns: 34px 1fr; }
  .badges { grid-column: 2; flex-direction: row; align-items: center; }
  header, .controls, main, .roadmap, footer { padding-left: 16px; padding-right: 16px; }
}
